<?php
declare(strict_types=1);
$base=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/admin/player-account.php')),'/');$root=preg_replace('#/admin$#','',$base)??'';$id=trim((string)($_GET['id']??''));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage player account · CORE</title><style>:root{color-scheme:dark;--bg:#0b1020;--panel:#141d32;--line:#2b3a57;--text:#edf3ff;--muted:#a9b8d2;--accent:#70d6c2}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#172744 0,#0b1020 60%);color:var(--text);font:16px/1.5 system-ui,sans-serif}main{width:min(100% - 28px,900px);margin:0 auto;padding:28px 0 60px}a{color:var(--accent)}section{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:22px;margin-top:16px}h1{margin:.3em 0;font-size:clamp(2rem,5vw,3rem)}p,.muted{color:var(--muted)}label{display:block;color:var(--muted);margin:12px 0 5px}input,select,button{font:inherit;min-height:44px;border-radius:8px}input,select{width:100%;padding:9px 12px;color:var(--text);background:#0b1325;border:1px solid #526585}button{padding:9px 14px;background:var(--accent);color:#08201d;font-weight:700;border:0;cursor:pointer;margin:5px 5px 0 0}button.secondary{background:#263752;color:var(--text);border:1px solid #3a4d6e}button.danger{background:#8c3345;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:12px}.status{padding:10px 12px;border-radius:7px;background:#202e48;overflow-wrap:anywhere}.status.error{background:#642c38}.status.success{background:#16463f}.id{font-family:ui-monospace,monospace;overflow-wrap:anywhere}.danger-zone{border-color:#8c3345}.fine{font-size:.9rem;color:var(--muted)}</style></head><body><main><a href="<?=htmlspecialchars($root,ENT_QUOTES)?>/index.php?tab=accounts">← Back to Player Accounts</a><header><p class="muted">CORE WORKBENCH · ACCOUNT MANAGEMENT</p><h1>Account details</h1><p>Review and edit this account. Passwords are never displayed; leave the new-password field blank to keep the existing password.</p></header><section><p id="status" class="status" role="status">Loading account…</p><form id="accountForm" hidden><div class="grid"><div><label for="email">Email address</label><input id="email" name="email" type="email" maxlength="254" required></div><div><label for="account_type">Account type</label><input id="account_type" name="account_type" maxlength="80" required></div><div><label for="statusSelect">Access status</label><select id="statusSelect" name="status"><option value="active">Active</option><option value="locked">Locked</option><option value="banned">Banned</option><option value="disabled">Disabled</option></select></div><div><label for="created_at">Created date/time (ISO 8601 or existing value)</label><input id="created_at" name="created_at" maxlength="80"></div></div><label for="new_password">Set new password (optional)</label><input id="new_password" name="new_password" type="password" minlength="10" maxlength="4096" autocomplete="new-password" placeholder="Leave blank to keep current password"><p class="fine">Account ID: <span id="accountId" class="id"></span></p><div><button type="submit">Save changes</button><button type="button" class="secondary" id="lockButton">Lock account</button><button type="button" class="secondary" id="banButton">Ban account</button><button type="button" class="secondary" id="activateButton">Activate account</button></div></form></section><section class="danger-zone"><h2>Archive account</h2><p>Archiving disables sign-in but preserves the account record and all character and universe ownership references. You can reactivate the account later.</p><p class="fine" id="archiveNotice" hidden></p><button type="button" class="danger" id="archiveButton" disabled>Archive account</button></section></main><script>
const accountId=<?=json_encode($id,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;const statusEl=document.getElementById('status'),form=document.getElementById('accountForm');let account=null;
async function request(action,extra={}){const r=await fetch('../api/player-accounts-admin.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action,id:accountId,...extra}),cache:'no-store'});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error?.message||'Request failed.');return d}
function message(t,kind=''){statusEl.textContent=t;statusEl.className='status '+kind}
async function load(){try{const d=await request('get');account=d.account;for(const key of ['email','account_type','created_at'])document.getElementById(key).value=account[key]||'';document.getElementById('statusSelect').value=['active','locked','banned','disabled'].includes(account.status)?account.status:'active';document.getElementById('accountId').textContent=account.id;form.hidden=false;document.getElementById('archiveButton').disabled=Boolean(account.archived_at);const archiveNotice=document.getElementById('archiveNotice');archiveNotice.hidden=!account.archived_at;archiveNotice.textContent=account.archived_at?'Archived at '+account.archived_at:'';document.getElementById('archiveButton').textContent=account.archived_at?'Account is archived':'Archive account';document.getElementById('lockButton').textContent=account.status==='locked'?'Account is locked':'Lock account';document.getElementById('banButton').textContent=account.status==='banned'?'Account is banned':'Ban account';message('Account loaded.','success')}catch(e){message(e.message,'error')}}
form.addEventListener('submit',async e=>{e.preventDefault();const payload={email:document.getElementById('email').value,account_type:document.getElementById('account_type').value,created_at:document.getElementById('created_at').value,status:document.getElementById('statusSelect').value,new_password:document.getElementById('new_password').value};try{const d=await request('update',payload);document.getElementById('new_password').value='';message(d.message,'success');await load()}catch(e){message(e.message,'error')}});
async function setStatus(value){document.getElementById('statusSelect').value=value;form.requestSubmit()};document.getElementById('lockButton').addEventListener('click',()=>setStatus('locked'));document.getElementById('banButton').addEventListener('click',()=>setStatus('banned'));document.getElementById('activateButton').addEventListener('click',()=>setStatus('active'));document.getElementById('archiveButton').addEventListener('click',async()=>{if(!confirm('Archive this account? Sign-in will be disabled, but the account and all associated character ownership records will be preserved.'))return;try{const d=await request('archive');message(d.message,'success');await load()}catch(e){message(e.message,'error')}});load();
</script></body></html>